function reverseDigits(n) {
  const negative = n < 0;
  const reversed = Number(String(Math.abs(n)).split("").reverse().join(""));
  const signed = negative ? -reversed : reversed;
  if (signed < -2147483648 || signed > 2147483647) return 0;
  return signed;
}

function reverseDigits(n) {
  const negative = n < 0;
  let rest = Math.abs(n);
  const limit = negative ? 2147483648 : 2147483647;
  let result = 0;
  while (rest > 0) {
    const digit = rest % 10;
    if (result > Math.floor((limit - digit) / 10)) return 0;
    result = result * 10 + digit;
    rest = Math.floor(rest / 10);
  }
  return negative ? -result : result;
}

