def int_to_roman(n):
    table = (
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    )
    rest = n
    pieces = []
    for value, symbol in table:
        count, rest = divmod(rest, value)
        pieces.append(symbol * count)
    return "".join(pieces)

